// The final three bytes of each real 2026-08-30 refusal tail, copied
// byte-for-byte so classification is adjudicated against the provider's own
// stream shape rather than a synthetic approximation.
const B332_D2_TAIL = Buffer.from('', 'base64').toString('utf8')
// The planner stream that ended lane b463-sessionbusy on 2026-09-06 at 07:39Z:
// four verbatim whole lines of its d6/stream.jsonl — an allowed_warning
// rate_limit_event, the rejected one stating resetsAt 1788695400, the
// <synthetic> assistant frame and the terminal result carrying
// api_error_status 429. Recorded, never hand-built (#968).
const B463_D6_TAIL = Buffer.from('', 'base64').toString('utf8')
const B333_D2_TAIL = Buffer.from('', 'base64').toString('utf8')
// The b401 d2 529 recording did not survive its lane archive and is not reproducible. DERIVED from the recorded 429 tail, and said to be: the
// rate_limit_event frame dropped (a 529 states no reset) and api_error_status
// set to 529 on the recorded result frame. Every other byte is the provider's.
const DERIVED_529_TAIL = B332_D2_TAIL
  .split('\n')
  .filter((line) => { try { return JSON.parse(line)?.type !== 'rate_limit_event' } catch { return true } })
  .map((line) => { let e; try { e = JSON.parse(line) } catch { return line } return e?.type === 'result' ? JSON.stringify({ ...e, api_error_status: 529 }) : line })
  .join('\n')
// [F12] budgetRefused is the CONJUNCTION of a <synthetic> assistant frame and
// an api error, so dropping that frame leaves a terminal server_error the
// collapsed bit does NOT flag. Routing that reads the bit never reaches it.
const DERIVED_529_UNREFUSED = DERIVED_529_TAIL
  .split('\n')
  .filter((line) => { try { const e = JSON.parse(line); return !(e?.type === 'assistant' && e.message?.model === '<synthetic>') } catch { return true } })
  .join('\n')

const B337_D1_AT_READ = Buffer.from("", 'base64').toString('utf8')
const B337_D1_RESULT = Buffer.from("", 'base64').toString('utf8')


// The b200-helperdedup envelope, byte-exact: 1921 bytes, schema-shaped, and
// unparseable on ONE literal newline inside the `summary` string value.
function b200Bytes(bytes = 1921) {
  const head = '{\n  "assignment_id": "d1",\n  "role": "builder",\n  "status": "done",\n  "summary": "deduplicated the helper\nand ran the lane green: '
  const tail = '",\n  "artifacts": ["/tmp/plan.md"],\n  "details": {}\n}\n'
  const raw = `${head}${'x'.repeat(bytes - Buffer.byteLength(head) - Buffer.byteLength(tail))}${tail}`
  assert.equal(Buffer.byteLength(raw), bytes)
  assert.throws(() => JSON.parse(raw), SyntaxError)
  return raw
}

function makeFixture(overrides = {}, roles = ['builder']) {
  const dir = mkdtempSync(join(tmpdir(), 'headless-extra-'))
  const taskDir = join(dir, 'task'); const returnsDir = join(dir, 'returns')
  mkdirSync(taskDir); mkdirSync(returnsDir)
  const members = Object.fromEntries(roles.map((role) => [role, { model: 'sonnet', transport: 'headless-json' }]))
  const crew = { checkout: dir, members }
  const calls = []
  const adapter = { headlessCommand(spec) { calls.push(spec); return { bin: '/worker/bin', args: ['-p', spec.prompt], env: {} } } }
  let nextPid = 700
  const deps = { pid: 700, uuid: (() => { let n = 0; return () => `extra-${++n}` })(), spawn() { return { pid: ++nextPid, unref() {} } }, log() {}, ...overrides }
  const io = headlessIo({ crew, paths: { dir, taskDir, returnsDir }, taskDir, checkout: dir, adapters: Object.fromEntries(roles.map((role) => [role, { adapter }])), bin: '/worker/bin', deps })
  return { dir, taskDir, returnsDir, crew, calls, deps, io, cleanup: () => rmSync(dir, { recursive: true, force: true }) }
}

function fixture(overrides = {}) {
  const dir = mkdtempSync(join(tmpdir(), 'headless-io-'))
  const taskDir = join(dir, 'task'); const returnsDir = join(dir, 'returns')
  mkdirSync(taskDir); mkdirSync(returnsDir)
  const crew = { checkout: dir, members: { builder: { model: 'sonnet', transport: 'headless-json' } } }
  const calls = []
  const adapter = { headlessCommand(spec) {
    calls.push(spec)
    return { bin: '/worker/bin', args: ['-p', spec.prompt, '--session-id', spec.sessionId], env: {} }
  } }
  let pid = 700
  const io = headlessIo({ crew, paths: { dir, taskDir, returnsDir }, taskDir, checkout: dir, adapters: { builder: { adapter } }, bin: '/worker/bin', deps: {
    spawn() { return { pid: ++pid, unref() {} } }, uuid: () => 'uuid-1', log() {}, ...overrides,
  } })
  return { dir, taskDir, returnsDir, crew, calls, io, cleanup: () => rmSync(dir, { recursive: true, force: true }) }
}

function timedFixture(overrides = {}) {
  let clock = 0
  let polls = 0
  const { onDelay = null, ...deps } = overrides
  let fixtureRef = null
  const f = makeFixture({
    ...deps,
    now: () => clock,
    delay: (ms) => {
      polls += 1
      clock += ms
      onDelay?.({ fixture: fixtureRef, clock, polls, ms })
    },
  })
  fixtureRef = f
  return { ...f, clock: () => clock, polls: () => polls }
}

test('classifyRun keeps all six worker traps distinct', () => {
  const cases = [
    ['ok', { exitCode: 0, terminal: true, sawJson: true, envelope: {}, timedOut: false }],
    ['ok-degraded', { exitCode: 137, terminal: false, sawJson: true, envelope: {}, timedOut: false }],
    ['aborted', { exitCode: 143, terminal: false, sawJson: true, envelope: null, timedOut: false }],
    ['no-envelope', { exitCode: 0, terminal: true, sawJson: true, envelope: null, timedOut: false }],
    ['malformed', { exitCode: 1, terminal: false, sawJson: false, envelope: null, timedOut: false }],
    ['timeout', { exitCode: null, terminal: false, sawJson: false, envelope: null, timedOut: true }],
  ]
  assert.deepEqual(cases.map(([expected, input]) => classifyRun(input)), cases.map(([expected]) => expected))
})

test('envelope wins over exit and stream evidence', () => {
  assert.equal(classifyRun({ exitCode: 137, terminal: false, sawJson: true, envelope: { status: 'done' }, timedOut: false }), 'ok-degraded')
})

test('a healthy run whose exit marker has not been written yet is ok', () => {
  const stream = parseStream('/fixture/b337-d1-at-read.jsonl', () => B337_D1_AT_READ, () => true)
  assert.deepEqual({ sawJson: stream.sawJson, terminal: stream.terminal }, { sawJson: true, terminal: false })
  assert.equal(classifyRun({
    exitCode: null, signal: null, terminal: stream.terminal, sawJson: stream.sawJson,
    envelope: { status: 'done' }, timedOut: false,
  }), 'ok')
  assert.deepEqual(degradedSignals({ exitCode: null, signal: null, terminal: false }), [])
})

test('degradedSignals names the signal that fired', () => {
  const cases = [
    [{ exitCode: 1, terminal: true }, ['exit-nonzero']],
    [{ exitCode: 137, terminal: true }, ['exit-signal']],
    [{ exitCode: 143, terminal: false }, ['exit-signal', 'terminal-missing']],
    [{ exitCode: 0, terminal: false }, ['terminal-missing']],
    [{ exitCode: 0, terminal: true }, []],
    [{ exitCode: null, terminal: false }, []],
    [{ exitCode: null, signal: 'SIGKILL', terminal: false }, ['exit-signal']],
  ]
  for (const [input, expected] of cases) assert.deepEqual(degradedSignals(input), expected)
})

test('decodeExitStatus separates signal numbers from wrapper exit codes', () => {
  assert.deepEqual(decodeExitStatus(143), { code: 143, signo: 15, signal: 'SIGTERM' })
  assert.deepEqual(decodeExitStatus(137), { code: 137, signo: 9, signal: 'SIGKILL' })
  assert.deepEqual(decodeExitStatus(0), { code: 0, signo: null, signal: null })
  assert.deepEqual(decodeExitStatus(200), { code: 200, signo: null, signal: null })
  assert.deepEqual(decodeExitStatus(null), { code: null, signo: null, signal: null })
  assert.deepEqual(decodeExitStatus(128 + 22), { code: 150, signo: 22, signal: null })
})

test('attributeExit names every measured exit cause and keeps unknown unmeasured', () => {
  assert.equal(attributeExit({ exitCode: 143, driverSignalled: true }), 'driver-retired')
  assert.equal(attributeExit({ exitCode: 143, driverSignalled: false }), 'external-signal')
  assert.equal(attributeExit({ exitCode: 0, driverSignalled: false }), 'self-exit')
  assert.equal(attributeExit({ exitCode: null, driverSignalled: true }), 'unknown')
})

test('stderrTail reports absence, unreadability, whole size, and the final bytes', () => {
  assert.deepEqual(stderrTail('/missing', { existsSync: () => false, readFileSync: () => '' }), {
    bytes: null, tail: null, truncated: false, reason: 'absent',
  })
  assert.doesNotThrow(() => {
    const result = stderrTail('/denied', {
      existsSync: () => true,
      readFileSync: () => { throw new Error('permission denied') },
    })
    assert.deepEqual(result, { bytes: null, tail: null, truncated: false, reason: 'unreadable' })
  })
  const marker = `${'padding'.repeat(20)}TAIL-MARKER`
  const long = stderrTail('/long', {
    existsSync: () => true, readFileSync: () => marker, limit: 'TAIL-MARKER'.length,
  })
  assert.deepEqual(long, { bytes: Buffer.byteLength(marker), tail: 'TAIL-MARKER', truncated: true, reason: null })
  const short = stderrTail('/short', { existsSync: () => true, readFileSync: () => 'short', limit: 100 })
  assert.deepEqual(short, { bytes: 5, tail: 'short', truncated: false, reason: null })
})

test('a signal-killed worker is distinguishable from an unwritten marker', () => {
  const logs = []
  const f = fixture({ log: (row) => logs.push(row) })
  try {
    const first = f.io.assign({ role: 'builder', briefFile: '/tmp/brief.md' })
    const firstDir = join(f.taskDir, 'headless', first.id)
    writeFileSync(join(firstDir, 'stream.jsonl'), B337_D1_AT_READ + B337_D1_RESULT)
    writeFileSync(join(firstDir, 'exit'), '137')
    writeFileSync(first.returnPath, JSON.stringify({ assignment_id: first.id, role: 'builder', status: 'done' }))
    assert.equal(f.io.wait(first.returnPath, 1).status, 'done')

    const second = f.io.assign({ role: 'builder', briefFile: '/tmp/brief.md' })
    const secondDir = join(f.taskDir, 'headless', second.id)
    writeFileSync(join(secondDir, 'stream.jsonl'), B337_D1_AT_READ)
    writeFileSync(second.returnPath, JSON.stringify({ assignment_id: second.id, role: 'builder', status: 'done' }))
    assert.equal(f.io.wait(second.returnPath, 1).status, 'done')

    const outcomes = logs.filter((row) => row.headless_outcome)
    assert.equal(outcomes.length, 2)
    assert.equal(outcomes[0].headless_outcome, 'ok-degraded')
    assert.deepEqual(outcomes[0].degraded, ['exit-signal'])
    assert.equal(outcomes[1].headless_outcome, 'ok')
    assert.equal(Object.hasOwn(outcomes[1], 'degraded'), false)
  } finally { f.cleanup() }
})

