const FALLBACK_TEST_CHAIN = [
  { provider: 'anthropic', id: 'claude-opus-5', agent: 'claude', effort: 'high', model: 'claude-opus-5' },
  { provider: 'anthropic', id: 'claude-sonnet-5', agent: 'claude', effort: 'high', model: 'claude-sonnet-5' },
]

function fallbackFixture(script, { chain = FALLBACK_TEST_CHAIN, clock = null, onSleep = null } = {}) {
  const dir = scratchDir('headless-fallback-')
  const taskDir = join(dir, 'task'); const returnsDir = join(dir, 'returns')
  mkdirSync(taskDir); mkdirSync(returnsDir)
  const member = {
    transport: 'headless-json', agent: 'claude', model: 'claude-fable-5',
    provider: 'anthropic', id: 'claude-fable-5', effort: 'high',
    ...(chain ? { fallback: chain.map((entry) => ({ ...entry })) } : {}),
  }
  const crew = { schema_version: 3, tier: 'judge', checkout: dir, members: { 'tech-lead': member }, seats: { 'tech-lead': { ...member, ...(member.fallback ? { fallback: member.fallback.map((entry) => ({ ...entry })) } : {}) } } }
  writeFileSync(join(dir, 'crew.json'), JSON.stringify(crew, null, 2))
  const journal = []; let spawns = 0; let pid = 4200; let lastRunDir = null
  const deps = {
    log: (row) => journal.push(row), kill: () => {},
    ...(clock ? { now: () => clock.t } : {}),
    sleep(ms) {
      if (clock) clock.t += Number(ms) || 0
      onSleep?.({ clock, runDir: lastRunDir, spawns, returnsDir })
    },
    uuid: (() => { let n = 0; return () => `fallback-${++n}` })(),
    spawn() {
      spawns += 1
      const root = join(taskDir, 'headless')
      const dirs = readdirSync(root).filter((name) => /^d\d+$/.test(name)).sort((a, b) => Number(a.slice(1)) - Number(b.slice(1)))
      lastRunDir = join(root, dirs.at(-1))
      script(spawns, lastRunDir, returnsDir)
      return { pid: ++pid, unref() {} }
    },
  }
  const io = headlessIo({ crew, paths: { dir, taskDir, returnsDir }, taskDir, checkout: dir, adapters: null, bin: '/frozen/worker/bin', deps })
  const commands = () => readdirSync(join(taskDir, 'headless')).filter((name) => /^d\d+$/.test(name)).sort((a, b) => Number(a.slice(1)) - Number(b.slice(1))).map((name) => JSON.parse(readFileSync(join(taskDir, 'headless', name, 'cmd.json'), 'utf8')))
  return {
    dir, taskDir, returnsDir, crew, journal, io, commands,
    spawnCount: () => spawns,
    diskCrew: () => JSON.parse(readFileSync(join(dir, 'crew.json'), 'utf8')),
    fallbackRows: () => journal.filter((row) => row.event === 'seat-fallback'),
    cleanup: () => rmSync(dir, { recursive: true, force: true }),
  }
}

function withTerminalStatus(tail, status) {
  return tail.split('\n').map((line) => {
    if (!line.trim()) return line
    let event
    try { event = JSON.parse(line) } catch { return line }
    if (event?.type !== 'result') return line
    return JSON.stringify({ ...event, api_error_status: status })
  }).join('\n')
}

function providerRetryFixture({ tail, at, refusals = 1, fallback = null, drift = 0, sleepThrows = false, spawnThrowsOn = 0, noExit = false, emit = null, emitThrows = false, clearRefuse = false }) {
  const dir = scratchDir('headless-provider-retry-')
  const taskDir = join(dir, 'task'); const returnsDir = join(dir, 'returns')
  mkdirSync(taskDir); mkdirSync(returnsDir)
  writeFileSync(join(taskDir, 'brief.md'), '# brief\n')
  const member = { model: 'claude-fable-5', transport: 'headless-json', ...(fallback ? { fallback } : {}) }
  const crew = { checkout: dir, members: { builder: member }, seats: { builder: { ...member } } }
  writeFileSync(join(dir, 'crew.json'), JSON.stringify(crew, null, 2))
  const journal = []; const parks = []; const polls = []; const beats = []; const parkSamples = []
  let clock = at; let spawns = 0; let pid = 9300; let clearRefused = false
  const crewJson = () => {
    try { return JSON.parse(readFileSync(join(dir, 'crew.json'), 'utf8')) } catch { return null }
  }
  const log = (row) => {
    journal.push(row)
    if (clearRefused && row?.event === 'crew-json-persist-failed') throw new Error('fixture: the journal refused the persist diagnostic')
  }
  const writeCrew = (path, data, options) => {
    if (clearRefuse && String(path).includes('crew.json') && /"park":\s*null/.test(String(data))) {
      clearRefused = true
      throw new Error('fixture: crew.json clear is unwritable')
    }
    return writeFileSync(path, data, options)
  }
  const writeRefusal = (runDir) => {
    writeFileSync(join(runDir, 'stream.jsonl'), tail)
    if (!noExit) writeFileSync(join(runDir, 'exit'), '1')
  }
  const writeAnswer = (runDir) => {
    writeFileSync(join(returnsDir, 'd1.builder.json'), JSON.stringify({ assignment_id: 'd1', role: 'builder', status: 'done' }))
    writeFileSync(join(runDir, 'stream.jsonl'), `${JSON.stringify({ type: 'result', terminal_reason: 'completed', subtype: 'success' })}\n`)
    writeFileSync(join(runDir, 'exit'), '0')
  }
  const io = headlessIo({
    crew, paths: { dir, taskDir, returnsDir }, taskDir, checkout: dir, adapters: null, bin: '/frozen/worker/bin',
    deps: {
      log,
      emit: emitThrows ? () => { throw new Error('fixture: emitter refused') } : (emit || ((event) => beats.push({ ...event }))),
      writeFileSync: writeCrew, kill: () => {}, uuid: () => 'provider-retry-session',
      now: () => clock,
      sleep(ms) {
        if (sleepThrows) { const error = new Error('seat died: builder — its worker root is gone'); error.stage = 'seat-died'; throw error }
        clock += ms; polls.push(ms)
      },
      delay(ms) { clock += ms + drift; parks.push(ms); parkSamples.push({ at: clock, park: crewJson()?.park ?? null }) },
      spawn() {
        spawns += 1
        if (spawns === spawnThrowsOn) throw new Error('spawn refused')
        const root = join(taskDir, 'headless')
        const dirs = readdirSync(root).filter((name) => /^d\d+$/.test(name)).sort((a, b) => Number(a.slice(1)) - Number(b.slice(1)))
        const runDir = join(root, dirs.at(-1))
        if (spawns <= refusals) writeRefusal(runDir)
        else writeAnswer(runDir)
        return { pid: ++pid, unref() {} }
      },
    },
  })
  const run = io.assign({ role: 'builder', briefFile: join(taskDir, 'brief.md') })
  return { io, run, journal, parks, polls, beats, parkSamples, crewJson, spawns: () => spawns, cleanup: () => rmSync(dir, { recursive: true, force: true }) }
}

function withoutTerminalStatus(tail) {
  return tail.split('\n').map((line) => {
    if (!line.trim()) return line
    let event
    try { event = JSON.parse(line) } catch { return line }
    if (event?.type !== 'result') return line
    const { api_error_status: _dropped, ...rest } = event
    return JSON.stringify(rest)
  }).join('\n')
}

function providerRetryError(f, timeoutS = 600) {
  try { f.io.wait(f.run.returnPath, timeoutS) } catch (error) { return error }
  assert.fail('expected provider retry fixture to end with an error')
}

function declinedBy(f, reason, timeoutS = 600) {
  const error = providerRetryError(f, timeoutS)
  assert.ok(String(error.message).includes(reason), `expected refusal reason ${reason}`)
  const declared = error.providerRetry?.declined
  assert.ok(typeof declared === 'string' && declared.includes(reason), `expected declined reason ${reason}`)
  const row = f.journal.find((entry) => entry.event === 'provider-retry-declined')
  if (row) assert.equal(row.why, declared)
  assert.ok(String(error.message).includes(String(declared)))
  return error
}

// The transport factory gets seat-io's deliberate provider-delay seam, then
// drives the real headless transport with recorded provider bytes. This makes
// the route and its seam observable together without invoking a worker binary.
function providerRetrySeatFixture({ tail, at, fallback = null, refusals = 1 }) {
  const dir = scratchDir('seat-provider-retry-')
  const taskDir = join(dir, 'task'); const returnsDir = join(dir, 'returns')
  mkdirSync(taskDir); mkdirSync(returnsDir)
  writeFileSync(join(taskDir, 'brief.md'), '# brief\n')
  const member = { model: 'claude-fable-5', transport: HEADLESS_TRANSPORT, agent: 'claude', ...(fallback ? { fallback } : {}) }
  const crew = { claude_bin: '/frozen/worker/bin', checkout: dir, members: { builder: member }, seats: { builder: { ...member } } }
  const journal = []; const sleeps = []
  let clock = at; let spawns = 0; let pid = 9400
  const writeRefusal = (runDir) => {
    writeFileSync(join(runDir, 'stream.jsonl'), tail)
    writeFileSync(join(runDir, 'exit'), '1')
  }
  const writeAnswer = (runDir) => {
    writeFileSync(join(returnsDir, 'd1.builder.json'), JSON.stringify({ assignment_id: 'd1', role: 'builder', status: 'done' }))
    writeFileSync(join(runDir, 'stream.jsonl'), `${JSON.stringify({ type: 'result', terminal_reason: 'completed', subtype: 'success' })}\n`)
    writeFileSync(join(runDir, 'exit'), '0')
  }
  const io = seatIo(crew, { dir, taskDir, returnsDir }, dir, null, {}, {}, {
    now: () => clock,
    sleep(ms) { clock += ms; sleeps.push(ms) },
    logLine: (_path, row) => journal.push(row),
    snapshot: () => ({ ok: true, rows: new Map() }),
    kill: () => {},
    spawnSync: () => ({ status: 1, stdout: '' }),
    headlessIo(transportArgs) {
      return headlessIo({
        ...transportArgs,
        deps: {
          ...transportArgs.deps,
          now: () => clock,
          uuid: () => 'provider-retry-seat-session',
          kill: () => {},
          spawn() {
            spawns += 1
            const root = join(taskDir, 'headless')
            const dirs = readdirSync(root).filter((name) => /^d\d+$/.test(name)).sort((a, b) => Number(a.slice(1)) - Number(b.slice(1)))
            const runDir = join(root, dirs.at(-1))
            if (spawns <= refusals) writeRefusal(runDir)
            else writeAnswer(runDir)
            return { pid: ++pid, unref() {} }
          },
        },
      })
    },
  })
  const run = io.assign({ role: 'builder', briefFile: join(taskDir, 'brief.md') })
  return { io, run, journal, sleeps, spawns: () => spawns, cleanup: () => rmSync(dir, { recursive: true, force: true }) }
}

function writeBudgetRefusal(runDir) {
  // Keep the legacy fallback fixture provider-unclassified: this path proves a
  // refusal with no recorded provider kind still spends the model fallback.
  const tail = B333_D2_TAIL.split('\n').map((line) => {
    if (!line.trim()) return line
    let event
    try { event = JSON.parse(line) } catch { return line }
    if (event?.type !== 'result') return line
    const { api_error_status: _status, ...withoutStatus } = event
    return JSON.stringify(withoutStatus)
  }).join('\n')
  writeFileSync(join(runDir, 'stream.jsonl'), tail)
  writeFileSync(join(runDir, 'exit'), '1')
}

function writeBudgetAnswer(runDir, returnsDir) {
  writeFileSync(join(returnsDir, 'd1.tech-lead.json'), JSON.stringify({ assignment_id: 'd1', role: 'tech-lead', status: 'done' }))
  writeFileSync(join(runDir, 'stream.jsonl'), `${JSON.stringify({ type: 'result', terminal_reason: 'completed', subtype: 'success' })}\n`)
  writeFileSync(join(runDir, 'exit'), '0')
}

test('a budget refusal re-asks the same assignment on the consumed fallback cell', () => {
  const f = fallbackFixture((n, runDir, returnsDir) => n === 1 ? writeBudgetRefusal(runDir) : writeBudgetAnswer(runDir, returnsDir))
  try {
    const run = f.io.assign({ role: 'tech-lead', briefFile: join(f.taskDir, 'brief.md') })
    const envelope = f.io.wait(run.returnPath, 600)
    assert.equal(envelope.assignment_id, 'd1')
    assert.equal(f.spawnCount(), 2)
    const commands = f.commands()
    assert.equal(commands[1].bin, '/frozen/worker/bin')
    assert.equal(commands[1].args[commands[1].args.indexOf('--model') + 1], 'claude-opus-5')
    const prompt = commands[1].args[commands[1].args.indexOf('-p') + 1]
    assert.match(prompt, /ASSIGNMENT d1:/)
    assert.equal(f.fallbackRows().length, 1)
    assert.deepEqual(f.fallbackRows()[0], {
      at: f.fallbackRows()[0].at, event: 'seat-fallback', role: 'tech-lead',
      from: { provider: 'anthropic', id: 'claude-fable-5', model: 'claude-fable-5', effort: 'high', agent: 'claude' },
      to: { provider: 'anthropic', id: 'claude-opus-5', model: 'claude-opus-5', effort: 'high', agent: 'claude' },
      cause: 'budget', assignment_id: 'd1',
    })
    for (const view of [f.crew.members['tech-lead'], f.crew.seats['tech-lead'], f.diskCrew().members['tech-lead'], f.diskCrew().seats['tech-lead']]) {
      assert.equal(view.provider, 'anthropic'); assert.equal(view.id, 'claude-opus-5'); assert.equal(view.model, 'claude-opus-5')
      assert.equal(view.fallback.length, 1); assert.equal(view.fallback[0].id, 'claude-sonnet-5')
    }
  } finally { f.cleanup() }
})

